/* Last Shift 0.2: first-person exploration; no external APIs. */
(()=>{
 'use strict';
 const C=window.ShiftCore,R=window.ShiftRooms,$=id=>document.getElementById(id),dialog=$('dialog');
 let state=C.createState(),location='map',modalKind='',lastTime=performance.now(),sound=false,audio=null,revealUntil=0,toastTimer;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const score=n=>n==null?'—':`${Number.isInteger(n)?n:n.toFixed(1).replace('.',',')}%`;
 const active=()=>['playing','epilogue'].includes(state.phase)&&!dialog.open;
 function sprite(id){const n=R.PLACEMENTS[id].atlas;return `<span class="painted-object" style="--sx:${n%5*25}%;--sy:${n<5?0:100}%" aria-hidden="true"></span>`;}
 function say(t){$('speech').textContent=t;}
 function toast(t){clearTimeout(toastTimer);$('toast').textContent=t;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3300);}
 function chime(type='ok'){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime;const notes=type==='wrong'?[230,195]:type==='pick'?[460]:[392,523,659];notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=f;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(0,now+i*.1);g.gain.linearRampToValueAtTime(.05,now+i*.1+.02);g.gain.exponentialRampToValueAtTime(.001,now+i*.1+.25);o.start(now+i*.1);o.stop(now+i*.1+.3);});}catch{}}
 function closeModal(){dialog.close();modalKind='';lastTime=performance.now();$('scene').focus({preventScroll:true});}
 function showModal(kind,title,body,actions,kicker='Станция «Вереск»'){
  modalKind=kind;$('toast').classList.remove('visible');
  $('dialog-content').innerHTML=`<p class="dialog-kicker">${esc(kicker)}</p><h2 id="dialog-title" class="dialog-title">${title}</h2><div class="dialog-body">${body}</div><div class="dialog-buttons">${actions.map((a,i)=>`<button class="btn ${a.secondary?'secondary':''}" data-action="${i}" ${a.disabled?'disabled':''}>${a.label}</button>`).join('')}</div>`;
  actions.forEach((a,i)=>$('dialog-content').querySelector(`[data-action="${i}"]`).addEventListener('click',a.run));if(!dialog.open)dialog.showModal();
 }
 function intro(){showModal('intro','Последняя смена',`<p class="quote">«Все люди эвакуированы. Почти всё важное — тоже. Остались мы с тобой».</p><p>Ты — маленький робот на станции «Вереск». Перед тобой четыре отсека и последние поручения ЛУЧа.</p><p><b>Выбирай комнаты на карте и осматривай вещи.</b> В каждой комнате ты видишь станцию от первого лица. Предметы прячутся среди обычной обстановки.</p><p>Неси по одной вещи к шлюзу на главной карте. На смену — пять минут. Осмотр и разговоры останавливают часы.</p><p class="dialog-note">Клик — осмотр. M — карта. Если трудно найти вещь, доступна помощь без штрафа.</p>`,[{label:'Начать смену',run:()=>{C.start(state);closeModal();say(C.ORDERS[0].intro);refresh();}}],'Четыре комнаты · одна маленькая история');}
 function navigate(next){if(!active()||!(next==='map'||R.ROOMS[next]))return;location=next;revealUntil=0;state.history.push({event:'visit',room:next});renderLocation();}
 function renderLocation(){
  const map=location==='map';$('station-map').hidden=!map;$('room-view').hidden=map;$('back-map').hidden=map;$('search-help').hidden=map;
  $('location-title').textContent=map?'Карта станции':R.ROOMS[location].name;
  $('location-note').textContent=map?'Выбери отсек. Капсула ждёт у центрального шлюза.':R.ROOMS[location].note;
  $('scene').setAttribute('aria-label',map?'Карта станции':`${R.ROOMS[location].name}, вид от первого лица. Нажмите на предмет для осмотра.`);
  $('explore-note').textContent=map?'Выбери отсек на карте':'Ищи вещи на столах и среди обстановки';$('items').classList.remove('reveal');$('context').textContent='';
  if(!map){const room=R.ROOMS[location];$('room-image').src=room.image;$('room-image').alt=`${room.name}: акварельный интерьер от первого лица`;
   const available=R.visible(state,location),ids=new Set(available.map(it=>it.id));
   const patches=state.items.filter(it=>R.PLACEMENTS[it.id].room===location&&!ids.has(it.id)).map(it=>{const [l,t,w,h]=R.patchBox(it.id);return `<div class="clean-zone" style="left:${l}%;top:${t}%;width:${w}%;height:${h}%"><img alt="" aria-hidden="true" src="${room.clean}" style="width:${10000/w}%;height:${10000/h}%;left:${-100*l/w}%;top:${-100*t/h}%"></div>`;}).join('');
   $('items').innerHTML=patches+available.map(it=>{const [l,t,w,h]=R.PLACEMENTS[it.id].box;return `<button class="native-item" id="item-${it.id}" aria-label="Осмотреть: ${esc(it.name)}" style="left:${l}%;top:${t}%;width:${w}%;height:${h}%"></button>`;}).join('');
   R.visible(state,location).forEach(it=>{const b=$(`item-${it.id}`);b.addEventListener('click',e=>{e.stopPropagation();if(active())inspect(it);});b.addEventListener('mouseenter',()=>{$('context').textContent='Осмотреть';});b.addEventListener('mouseleave',()=>{$('context').textContent='';});});
  }$('room-view').classList.toggle('technical',location==='technical');
 }
 function refresh(){const final=['epilogue','ended'].includes(state.phase),o=C.currentOrder(state);$('order-count').textContent=final?'4 / 4':`${state.orderIndex+1} / 4`;$('order-title').textContent=final?'Ещё один пассажир':o.title;$('order-text').textContent=final?'Модуль памяти ЛУЧа в техническом отделе. Забрать его или отправиться одному — решать тебе.':o.text;$('progress').innerHTML=C.ORDERS.map((_,i)=>`<i class="${i<state.results.length?'done':i===state.orderIndex?'current':''}"></i>`).join('');$('hint').disabled=final;$('rating').textContent=score(C.rating(state));$('carry-name').textContent=state.carry?C.item(state,state.carry).name:'Пока ничего';$('carry-icon').innerHTML=state.carry?sprite(state.carry):'';$('inspect').disabled=!state.carry;$('drop').disabled=!state.carry;$('saved').innerHTML=state.saved.length?state.saved.map(id=>`<span class="saved-item" title="${esc(C.item(state,id).name)}">${sprite(id)}</span>`).join(''):'<span class="empty-saved">Здесь скоро станет уютнее</span>';$('gate-note').textContent=final?'В капсулу':state.carry?'Отправить вещь':'Отправка груза';$('hatch').classList.toggle('ready',!!state.carry||final);renderLocation();}
 function inspect(it){showModal('inspect',esc(it.name),`<div class="inspect-paint">${sprite(it.id)}</div><p>${esc(it.description)}</p><div class="facts">${it.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div>`,[{label:'Закрыть',secondary:true,run:closeModal},...(state.carry===it.id?[]:[{label:state.carry?'Руки заняты':'Взять с собой',disabled:!!state.carry,run:()=>{if(C.pickup(state,it.id)){state.history.push({event:'pickup',room:location,item:it.id});closeModal();refresh();chime('pick');toast('Вещь в руках. Вернись на карту и отправь её через шлюз.');}}}])],'Осмотр · время остановлено');}
 function returnItem(){if(!state.carry)return;const id=state.carry;if(R.returnHome(state)){state.history.push({event:'return',item:id});refresh();toast(`Вещь возвращена на место: ${R.ROOMS[R.PLACEMENTS[id].room].name}.`);}}
 function openGate(){if(!active())return;if(state.phase==='epilogue'){const rescue=state.carry==='memory';showModal('depart',rescue?'Место для двоих':'Отправиться одному?',`<p class="quote">${rescue?'«По инструкции здесь должен быть только один пассажир».':'«Я прослежу за запуском. У меня… ещё кое-какие дела».'}</p><p>${rescue?'Модуль ЛУЧа уже у тебя. В капсуле найдётся место для ещё одного воспоминания.':'Модуль памяти остался в техническом отделе. Можно вернуться за ним. На рейтинг это не повлияет.'}</p>`,[{label:'Ещё побуду',secondary:true,run:closeModal},{label:rescue?'Забрать ЛУЧа и улететь':'Улететь одному',run:()=>{C.finish(state);closeModal();refresh();ending();}}]);return;}if(!state.carry){toast('Выбери отсек и принеси вещь для текущего поручения.');return;}const it=C.item(state,state.carry);showModal('send','Отправить в капсулу?',`<div class="inspect-paint">${sprite(it.id)}</div><p><b>${esc(it.name)}</b></p><p class="quote">${esc(C.currentOrder(state).text)}</p><p class="dialog-note">Оценивается только отправка. Осмотр и переноска не снижают рейтинг.</p>`,[{label:'Ещё подумаю',secondary:true,run:closeModal},{label:'Отправить',run:send}],'Грузовой шлюз · проверка поручения');}
 function send(){closeModal();const r=C.submit(state);refresh();say(r.text);chime(r.type==='wrong'?'wrong':'ok');if(r.type==='wrong')showModal('wrong','Не совсем по инструкции',`<p class="quote">${esc(r.text)}</p><p>Вещь вернулась на своё место в отсеке. Можно принести другую.</p><p><b>−10 баллов за эту попытку.</b><br>За это поручение ещё можно получить ${100-r.penalty} из 100.</p>`,[{label:'Исправлюсь',run:closeModal}],'ЛУЧ проверил только явные условия');else if(r.type==='accepted')showModal('accepted',r.points===100?'Команда выполнена':'Исправление принято',`<p class="quote">${esc(r.text)}</p><p><b>${r.points} / 100 за поручение.</b> Все подходящие трактовки равноценны.</p>`,[{label:r.finished?'Закончить смену':'Следующее поручение',run:()=>{closeModal();if(r.finished)epilogue(false);else{say(C.currentOrder(state).intro);refresh();}}}],'Верность команд');}
 function epilogue(timeout){if(state.carry)R.returnHome(state);refresh();say('Осталось отключить ненужное оборудование. Меня. Но можете сначала закончить уборку.');showModal('epilogue','Приказы закончились',`${timeout?'<p>Время вышло. Незавершённые поручения получили 0 баллов.</p>':''}<p class="quote">«Осталось отключить ненужное оборудование. Меня. Но можете сначала закончить уборку».</p><p>В <b>техническом отделе</b> открылся доступ к съёмному модулю памяти ЛУЧа. Можно забрать его и улететь вместе.</p><p class="dialog-note">Часы остановлены. Этот выбор не меняет рейтинг.</p>`,[{label:'Я ещё кое-что забыл',run:closeModal}],'Последнее решение — твоё');}
 function ending(){showModal('ending',state.rescued?'Последняя смена. Вместе.':'Курс домой',`<div class="score-result">${score(C.rating(state))}<small>верность команд</small></div><p class="quote">${state.rescued?'«По инструкции здесь должен быть только один пассажир».<br>Робот подвигается. За иллюминатором медленно исчезает станция.':'«Курс проложен. Хорошей дороги, маленький».<br>Голос ЛУЧа становится тише. В капсуле остаются спасённые вещи.'}</p><table class="results"><tbody>${state.results.map(r=>`<tr><td>${esc(C.ORDERS[r.order].title)}<span class="result-item">${r.item?esc(C.item(state,r.item).name):'Не завершено'}${r.errors?` · ошибок: ${r.errors}`:''}</span></td><td>${r.points} / 100</td></tr>`).join('')}</tbody></table><p class="dialog-note">${state.rescued?'ЛУЧ спасён. ':''}Ответы ЛУЧа подготовлены заранее. Журнал поможет проверить команды и поиск вещей.</p>`,[{label:'Скачать журнал смены',secondary:true,run:downloadLog},{label:'Ещё одна смена',run:restart}],'Смена завершена');}
 function downloadLog(){const log={game:'Последняя смена',version:'0.3',rating:C.rating(state),rescued:state.rescued,elapsedActiveSeconds:Math.round(300-state.remaining),orders:state.results,events:state.history};const url=URL.createObjectURL(new Blob([JSON.stringify(log,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='last-shift-playtest-v2.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function restart(){if(dialog.open)closeModal();state=C.createState();location='map';revealUntil=0;refresh();say('Все люди эвакуированы. Почти всё важное — тоже. Остались мы с тобой.');intro();}
 function pause(){if(!active())return;showModal('pause','Небольшой перерыв','<p class="quote">«Пауза согласована. Я тоже пока подумаю о… техническом обслуживании».</p><p>Часы остановлены. Вещи остаются на своих местах.</p>',[{label:'Продолжить смену',run:closeModal}]);}
 function closeInfo(){closeModal();if(state.phase==='intro')intro();}
 $('help').addEventListener('click',()=>showModal('help','Как проходит смена','<p>На карте выбери отсек. Внутри ищи небольшие вещи среди обстановки и нажимай на них для осмотра.</p><p>Возьми одну вещь, вернись на карту и нажми «Шлюз». Неправильная отправка отнимает 10 баллов у поручения. Вещь возвращается в свою комнату.</p><p>«Помочь с поиском» на несколько секунд обводит доступные предметы. Подсказки и осмотр не снижают рейтинг; во время диалогов часы стоят.</p><p>M — карта. F — осмотреть вещь в руках. Q — вернуть её на исходное место. Esc — пауза. Tab и Enter — управление без мыши.</p>',[{label:'Понятно',run:closeInfo}],'Управление и правила'));
 $('rating-help').addEventListener('click',()=>showModal('rating','Верность команд','<p>Каждое выполненное поручение даёт 100 баллов. Все предусмотренные разумные трактовки равноценны.</p><p>Ошибочная отправка отнимает 10 баллов у текущего поручения, до минимума 0. Не завершённое вовремя поручение получает 0.</p><p>Итог — среднее по четырём поручениям. Во время игры — среднее по завершённым. Поиск, осмотр, помощь и финальный выбор на оценку не влияют.</p>',[{label:'Вернуться',run:closeInfo}]));
 $('hint').addEventListener('click',()=>{if(state.phase!=='playing')return;showModal('hint','Небольшое уточнение',`<p class="quote">${esc(C.hint(state))}</p><p class="dialog-note">Верность команд не изменилась.</p>`,[{label:'Теперь понятнее',run:closeModal}],'ЛУЧ на связи');});
 $('search-help').addEventListener('click',()=>{if(!active())return;revealUntil=performance.now()+4500;$('items').classList.add('reveal');state.history.push({event:'search-help',room:location});toast('На несколько секунд отметил вещи. Штрафа нет.');});
 document.querySelectorAll('[data-room]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.room)));
 $('back-map').addEventListener('click',()=>navigate('map'));$('hatch').addEventListener('click',openGate);$('inspect').addEventListener('click',()=>{if(state.carry)inspect(C.item(state,state.carry));});$('drop').addEventListener('click',returnItem);$('pause').addEventListener('click',pause);
 $('restart').addEventListener('click',()=>showModal('restart','Начать сначала?','<p>Все вещи вернутся на места. Поручения и рейтинг будут сброшены.</p>',[{label:'Продолжить эту смену',secondary:true,run:closeInfo},{label:'Начать заново',run:restart}]));
 $('sound').addEventListener('click',()=>{sound=!sound;$('sound').textContent=sound?'Звук: вкл.':'Звук: выкл.';$('sound').setAttribute('aria-pressed',String(sound));if(sound)chime('pick');});
 $('room-image').addEventListener('click',()=>{if(active())$('context').textContent='Ничего переносного. Попробуй осмотреть сами вещи.';});
 window.addEventListener('keydown',e=>{if(dialog.open||e.repeat)return;if(e.code==='Escape'){e.preventDefault();pause();}if(!active())return;if(e.code==='KeyM')navigate('map');if(e.code==='KeyF'&&state.carry)inspect(C.item(state,state.carry));if(e.code==='KeyQ')returnItem();});
 window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});dialog.addEventListener('cancel',e=>{e.preventDefault();if(['intro','ending','epilogue','accepted','wrong'].includes(modalKind))return;closeInfo();});
 setInterval(()=>{const now=performance.now(),dt=Math.min(1,(now-lastTime)/1000);lastTime=now;if(active()&&C.tick(state,dt))epilogue(true);const t=Math.ceil(state.remaining);$('timer').textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;$('timer').classList.toggle('urgent',t<60);if(revealUntil&&now>revealUntil){$('items').classList.remove('reveal');revealUntil=0;}$('steam').classList.toggle('visible',state.phase==='playing'&&(300-state.remaining)%18>15);},100);
 Object.values(R.ROOMS).forEach(r=>{for(const src of [r.image,r.clean]){const i=new Image();i.src=src;}});refresh();intro();
})();
